export function getParamFromHash(key: string): string {
  // 优先从 URL search params 中获取（History API 模式）
  const searchParams = new URLSearchParams(window.location.search);
  const fromSearch = searchParams.get(key);
  if (fromSearch) return fromSearch;

  // 兼容旧的 hash 模式
  const { hash } = window.location;
  if (!hash) {
    return '';
  }
  console.log('getParamFromHash===', hash);
  const urlParams = new URLSearchParams(hash.split('?')[1] || '');
  return urlParams.get(key) || '';
}

/**
 * 检查是否应该展示 Debug Viewer 的 UI 面板
 *
 * 默认不展示调试 UI；仅当 URL 中包含 showDebugViewer=true 时才展示。
 * 支持三种来源：
 *   1. window.location.search（如 ?showDebugViewer=true）
 *   2. window.location.hash 中的查询参数（如 #/viewer2?showDebugViewer=true）
 *
 * 当任一来源返回 "true" 时，返回 true
 */
export function getShowDebugViewer(): boolean {
  try {
    // 来源1：顶层 search 参数
    const searchParams = new URLSearchParams(window.location.search);
    if (searchParams.get('showDebugViewer') === 'true') return true;
    // 来源2：hash 中的查询参数
    const { hash } = window.location;
    const hashQueryIndex = hash.indexOf('?');
    if (hashQueryIndex >= 0) {
      const hashParams = new URLSearchParams(hash.substring(hashQueryIndex));
      if (hashParams.get('showDebugViewer') === 'true') return true;
    }
  } catch {
    // 忽略解析异常
  }

  return false;
}

/**
 * 异步校验当前用户是否命中「二次分享」OpenID 白名单。
 *
 * 与 3d-gaussian-splatting-viewer/metaverse/debug-panel.ts 保持一致的判定：
 *   getParamFromHash('openid') && openidList && openidList.includes(openid)
 *
 * 用途：
 *   1. 外层 SceneViewer / DebugSceneViewer：命中白名单时，即使 URL 没有 showDebugViewer=true
 *      也把 DebugPanel 渲染出来（让授权用户直接看到「允许二次分享」开关）。
 *   2. DebugPanel 自身：命中白名单时显示「📤 分享」分区并自动展开面板。
 *
 * 为避免一次会话内重复请求 /mini_app/get_openid_config，模块级缓存 Promise；
 * 校验失败 / 网络异常一律返回 false（不阻塞渲染）。
 */
let openidWhitelistPromise: Promise<boolean> | null = null;
export function checkOpenidWhitelist(): Promise<boolean> {
  if (openidWhitelistPromise) return openidWhitelistPromise;
  openidWhitelistPromise = (async () => {
    try {
      const openid = getParamFromHash('openid');
      if (!openid) return false;
      // 动态 import 避免在不需要的页面上把 api 模块打进首屏
      const { getOpenidConfig } = await import('../api/index');
      const openidList = await getOpenidConfig();
      console.log('[checkOpenidWhitelist] openidList:', openidList, 'openid:', openid);
      return Boolean(openidList && openidList.includes(openid));
    } catch (error) {
      console.error('[checkOpenidWhitelist] 校验失败:', error);
      return false;
    }
  })();
  return openidWhitelistPromise;
}
